using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class SetupWreckage
{
 const string Mod="Assets/Blueprinter/Mods/Gunmageddon/",Dir=Mod+"Wreckage/";
 static readonly Dictionary<Material,Material> Materials=new Dictionary<Material,Material>();static Texture2D soot;
 static void Set(UnityEngine.Object obj,string name,object value){var s=new SerializedObject(obj);var p=s.FindProperty(name);if(p==null)throw new Exception(obj.GetType()+" lacks "+name);if(value is float)p.floatValue=(float)value;else p.objectReferenceValue=value as UnityEngine.Object;s.ApplyModifiedPropertiesWithoutUndo();}
 static bool Temporary(Transform t){for(var p=t;p;p=p.parent){string n=p.name.ToLowerInvariant();if(n.Contains("loadinground")||n.Contains("ejectedcase")||n.Contains("spentcase")||n.Contains("powdercase")||n.Contains("projectile")||n=="shell_loaded"||n=="shell_casing"||n.Contains("rammer")||n.Contains("crank")||n.Contains("lensglow")||n.Contains("lensglare")||n.Contains("searchlightbeam")||n.Contains("topattacksubmunitiontemplate"))return true;}return false;}
 static Material Burn(Material original){if(!original)throw new Exception("Missing source material");Material result;if(Materials.TryGetValue(original,out result))return result;result=new Material(original);result.name="Wreck_"+original.name;bool concrete=original.name.IndexOf("concrete",StringComparison.OrdinalIgnoreCase)>=0||original.name.IndexOf("casemate",StringComparison.OrdinalIgnoreCase)>=0;
  if(!result.HasProperty("_BaseColor")||!result.HasProperty("_DetailAlbedoMap"))throw new Exception("Unsupported wreck material: "+original.name+" / "+original.shader.name);
  result.shader=AssetDatabase.LoadAssetAtPath<Shader>(Dir+"WreckScorch.shader");result.shaderKeywords=new string[0];result.SetTexture("_BaseMap",original.GetTexture("_BaseMap"));result.SetTexture("_BumpMap",original.GetTexture("_BumpMap"));result.SetTextureScale("_BaseMap",original.GetTextureScale("_BaseMap"));result.SetTextureOffset("_BaseMap",original.GetTextureOffset("_BaseMap"));result.SetFloat("_BumpScale",original.GetFloat("_BumpScale"));result.SetColor("_BaseColor",original.GetColor("_BaseColor")*(concrete?.60f:.32f));var c=result.GetColor("_BaseColor");c.a=1;result.SetColor("_BaseColor",c);result.SetTexture("_SootMap",soot);result.SetTextureScale("_SootMap",new Vector2(6,6));result.SetFloat("_Smoothness",.07f);result.SetFloat("_Metallic",.05f);result.SetColor("_EmissionColor",Color.black);result.renderQueue=-1;
  string path=Dir+"Materials/"+result.name.Replace('/','_')+"_"+AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(original))+".mat";AssetDatabase.CreateAsset(result,path);Materials.Add(original,result);return result;
 }
 static void MakeSoot(){soot=new Texture2D(128,128,TextureFormat.RGBA32,true,false);soot.name="Shared_Wreck_Soot";soot.wrapMode=TextureWrapMode.Repeat;soot.filterMode=FilterMode.Trilinear;var colors=new Color[128*128];for(int y=0;y<128;y++)for(int x=0;x<128;x++){float u=x/128f*Mathf.PI*2,v=y/128f*Mathf.PI*2;float n=.5f+.22f*Mathf.Sin(u*3+Mathf.Sin(v*2))+.15f*Mathf.Cos(v*5+Mathf.Sin(u*4))+.08f*Mathf.Sin(u*17+v*13);float value=Mathf.Lerp(.24f,.64f,Mathf.Clamp01(n));colors[y*128+x]=new Color(value,value*.91f,value*.79f,1);}soot.SetPixels(colors);soot.Apply(true,false);AssetDatabase.CreateAsset(soot,Dir+"Shared_Wreck_Soot.asset");}
 public static object Run(){if(EditorApplication.isPlaying||EditorApplication.isCompiling)throw new Exception("Stable edit mode required");if(AssetDatabase.IsValidFolder(Dir.TrimEnd('/')))throw new Exception("Wreckage destination exists; initial migration refuses overwrite");var paths=AssetDatabase.FindAssets("t:Prefab",new[]{Mod}).Select(AssetDatabase.GUIDToAssetPath).Where(p=>{var go=AssetDatabase.LoadAssetAtPath<GameObject>(p);var u=go.GetComponent<Unit>();if(!(u is Building||u is GroundVehicle))return false;return !new SerializedObject(u).FindProperty("wreckage").objectReferenceValue;}).ToArray();if(paths.Length!=15)throw new Exception("Expected15missing platform wrecks, got"+paths.Length);
  var original=SceneManager.GetActiveScene();string backup="Assets/BlueprinterSetupBackups/Wreckage";Directory.CreateDirectory(Path.Combine(Application.dataPath,"BlueprinterSetupBackups/Wreckage"));AssetDatabase.Refresh();if(!EditorSceneManager.SaveScene(original,backup+"/BeforeWreckage.unity",true))throw new Exception("Scene copy failed");foreach(var path in paths)if(!AssetDatabase.CopyAsset(path,backup+"/"+Path.GetFileName(path)))throw new Exception("Prefab backup failed: "+path);
  AssetDatabase.CreateFolder(Mod.TrimEnd('/'),"Wreckage");AssetDatabase.CreateFolder(Dir.TrimEnd('/'),"Materials");File.Copy(System.IO.Path.Combine((System.Environment.GetEnvironmentVariable("GUNMAGGEDON_ROOT") ?? throw new System.InvalidOperationException("Set GUNMAGGEDON_ROOT before running editor tools or fixtures.")), "GunmaggedonRuntime/tools/WreckScorch.shader"),Path.Combine(Application.dataPath,"Blueprinter/Mods/Gunmageddon/Wreckage/WreckScorch.shader"));AssetDatabase.ImportAsset(Dir+"WreckScorch.shader",ImportAssetOptions.ForceSynchronousImport);MakeSoot();Materials.Clear();var scene=EditorSceneManager.NewPreviewScene();var rows=new List<object>();
  try{foreach(var path in paths){var source=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(path));SceneManager.MoveGameObjectToScene(source,scene);source.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);bool trailer=source.GetComponent<GroundVehicle>();bool bunker=source.transform.Find("BunkerStructure");var pitches=new HashSet<Transform>();foreach(var turret in source.GetComponentsInChildren<Turret>(true)){var p=new SerializedObject(turret).FindProperty("elevationTransform").objectReferenceValue as Transform;if(p)pitches.Add(p);if(!bunker)turret.transform.localRotation*=Quaternion.Euler(0,13,0);}foreach(var gun in source.GetComponentsInChildren<Gun>(true))if(gun.transform.name.IndexOf("Pitch",StringComparison.OrdinalIgnoreCase)>=0)pitches.Add(gun.transform);foreach(var pitch in pitches)pitch.localRotation=Quaternion.Euler(bunker?3:12,0,0);Physics.SyncTransforms();
   var wreck=new GameObject(source.name.Replace("(Clone)","")+"_Wreck");SceneManager.MoveGameObjectToScene(wreck,scene);wreck.layer=0;var originals=new HashSet<Renderer>();foreach(var group in source.GetComponentsInChildren<LODGroup>(true))foreach(var renderer in group.GetLODs()[0].renderers)if(renderer)originals.Add(renderer);if(originals.Count==0)throw new Exception("Source lacks near LOD: "+path);
   foreach(var r in originals.OfType<MeshRenderer>()){if(!r.gameObject.activeInHierarchy||Temporary(r.transform))continue;var mesh=r.GetComponent<MeshFilter>();if(!mesh||!mesh.sharedMesh)continue;var part=new GameObject(r.name);part.transform.SetParent(wreck.transform,false);part.transform.SetPositionAndRotation(r.transform.position,r.transform.rotation);part.transform.localScale=r.transform.lossyScale;part.layer=0;part.AddComponent<MeshFilter>().sharedMesh=mesh.sharedMesh;var copy=part.AddComponent<MeshRenderer>();EditorUtility.CopySerialized(r,copy);copy.enabled=true;copy.sharedMaterials=r.sharedMaterials.Select(Burn).ToArray();}
   if(trailer){foreach(var collider in source.GetComponentsInChildren<Collider>(true)){if(collider.isTrigger||!collider.enabled||!collider.gameObject.activeInHierarchy||Temporary(collider.transform))continue;var b=collider.bounds;if(b.size.sqrMagnitude<.001f)continue;var box=wreck.AddComponent<BoxCollider>();box.center=b.center;box.size=b.size;}var component=wreck.AddComponent<Wreckage>();var rb=source.GetComponent<Rigidbody>();Set(component,"mass",rb?rb.mass:2000f);}
   else{foreach(var collider in source.GetComponentsInChildren<Collider>(true)){if(collider.isTrigger||!collider.enabled||!collider.gameObject.activeInHierarchy||Temporary(collider.transform))continue;var go=new GameObject("WreckCollision");go.transform.SetParent(wreck.transform,false);go.transform.SetPositionAndRotation(collider.transform.position,collider.transform.rotation);go.transform.localScale=collider.transform.lossyScale;var copy=go.AddComponent(collider.GetType()) as Collider;EditorUtility.CopySerialized(collider,copy);copy.isTrigger=false;}}
   SetupUnitLODs.ConfigureCarriage(wreck);var groupW=wreck.GetComponent<LODGroup>();var levels=groupW.GetLODs();var triangles=levels.Select(l=>l.renderers.Sum(r=>r.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3)).ToArray();if(!(triangles[0]>triangles[1]&&triangles[1]>triangles[2]))throw new Exception("Wreck LOD reduction failed: "+path);var prefab=PrefabUtility.SaveAsPrefabAsset(wreck,Dir+wreck.name+".prefab");var live=PrefabUtility.LoadPrefabContents(path);try{Set(live.GetComponent<Unit>(),"wreckage",prefab);PrefabUtility.SaveAsPrefabAsset(live,path);}finally{PrefabUtility.UnloadPrefabContents(live);}rows.Add(new{unit=source.GetComponent<Unit>().definition.unitName,source=path,wreck=AssetDatabase.GetAssetPath(prefab),trailer,triangles});UnityEngine.Object.DestroyImmediate(source);UnityEngine.Object.DestroyImmediate(wreck);
  }AssetDatabase.SaveAssets();string json=Newtonsoft.Json.JsonConvert.SerializeObject(new{units=rows,materials=Materials.Count,sharedDetailTextures=1,sourceSceneSaved=false});string output=System.IO.Path.Combine((System.Environment.GetEnvironmentVariable("GUNMAGGEDON_ROOT") ?? throw new System.InvalidOperationException("Set GUNMAGGEDON_ROOT before running editor tools or fixtures.")), "GunmaggedonRuntime/build/wreckage");Directory.CreateDirectory(output);File.WriteAllText(output+"/setup.json",json);return json;}finally{EditorSceneManager.ClosePreviewScene(scene);}
 }
}
